class Solution {
    public String simplifyPath(String path) {
        String[] parts = path.split("/");
        List<String> list = new ArrayList<>();
        for (String p : parts) {
            if (p.equals("") || p.equals(".")) continue;
            if (p.equals("..")) { if (!list.isEmpty()) list.remove(list.size() - 1); }
            else list.add(p);
        }
        return "/" + String.join("/", list);
    }
}

